import{_ as a,c as e,o,a0 as s}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance.","frontmatter":{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance."},"headers":[],"relativePath":"pt/blog/elite-goal-setting.md","filePath":"pt/blog/elite-goal-setting.md"}');const t=a({name:"pt/blog/elite-goal-setting.md"},[["render",function(a,i,t,r,l,n){return o(),e("div",null,[...i[0]||(i[0]=[s('<h1 id="definicao-de-metas-para-atletas-de-elite" tabindex="-1">Definição de metas para atletas de elite <a class="header-anchor" href="#definicao-de-metas-para-atletas-de-elite" aria-label="Permalink to &quot;Definição de metas para atletas de elite&quot;">​</a></h1><p>Definir metas parece simples: decida o que você quer e trabalhe para alcançar isso. Mas a definição de metas em alto nível é mais complexa. As metas certas aceleram o desenvolvimento; as erradas criam frustração e estagnação.</p><h2 id="alem-dos-objetivos-basicos" tabindex="-1">Além dos objetivos básicos <a class="header-anchor" href="#alem-dos-objetivos-basicos" aria-label="Permalink to &quot;Além dos objetivos básicos&quot;">​</a></h2><p>A maioria dos jogadores estabelece metas de resultado: &quot;Ganhar o campeonato regional&quot;. Essas metas apresentam problemas:</p><ul><li>Você não pode controlar totalmente os resultados.</li><li>Eles criam pressão sem direção.</li><li>Sucesso ou fracasso é binário</li><li>Eles não orientam a prática diária.</li></ul><p>O estabelecimento de metas de elite vai além disso.</p><h2 id="a-hierarquia-de-objetivos" tabindex="-1">A Hierarquia de Objetivos <a class="header-anchor" href="#a-hierarquia-de-objetivos" aria-label="Permalink to &quot;A Hierarquia de Objetivos&quot;">​</a></h2><h3 id="nivel-1-objetivos-dos-sonhos-1-5-anos" tabindex="-1">Nível 1: Objetivos dos Sonhos (1-5 anos) <a class="header-anchor" href="#nivel-1-objetivos-dos-sonhos-1-5-anos" aria-label="Permalink to &quot;Nível 1: Objetivos dos Sonhos (1-5 anos)&quot;">​</a></h3><p>Suas maiores aspirações:</p><ul><li>&quot;Competir a nível nacional&quot;</li><li>&quot;Seja reconhecido como um atirador de elite&quot;</li><li>&quot;Ganhar um grande campeonato&quot;</li></ul><p>Essas dicas fornecem direção e motivação, mas não são aplicáveis no dia a dia.</p><h3 id="nivel-2-metas-de-desempenho-temporada-ano" tabindex="-1">Nível 2: Metas de desempenho (temporada/ano) <a class="header-anchor" href="#nivel-2-metas-de-desempenho-temporada-ano" aria-label="Permalink to &quot;Nível 2: Metas de desempenho (temporada/ano)&quot;">​</a></h3><p>Melhorias mensuráveis no seu jogo:</p><ul><li>&quot;Aumentar a precisão de tiro de 60% para 70%&quot;</li><li>&quot;Reduzir erros não forçados em 25%&quot;</li><li>&quot;Desenvolver um plombée confiável&quot;</li></ul><p>Essas coisas estão sob seu controle e são mensuráveis.</p><h3 id="nivel-3-metas-de-processo-diarias-semanais" tabindex="-1">Nível 3: Metas de Processo (Diárias/Semanais) <a class="header-anchor" href="#nivel-3-metas-de-processo-diarias-semanais" aria-label="Permalink to &quot;Nível 3: Metas de Processo (Diárias/Semanais)&quot;">​</a></h3><p>As ações que impulsionam a melhoria:</p><ul><li>&quot;Execute a rotina completa antes de cada arremesso&quot;</li><li>&quot;Pratique a visualização por 10 minutos diariamente&quot;</li><li>&quot;Treine a técnica de arremesso 3 vezes por semana&quot;</li></ul><p>Esses fatores são totalmente controláveis e contribuem para o alcance de metas de desempenho.</p><h2 id="o-framework-smart" tabindex="-1">O Framework SMART+ <a class="header-anchor" href="#o-framework-smart" aria-label="Permalink to &quot;O Framework SMART+&quot;">​</a></h2><p>Vá além das metas SMART básicas:</p><h3 id="especifico" tabindex="-1">Específico <a class="header-anchor" href="#especifico" aria-label="Permalink to &quot;Específico&quot;">​</a></h3><p>Não se trata de &quot;melhorar minha pontaria&quot;, mas sim de &quot;desenvolver um demi-portée consistente que acerte o alvo a 30 cm do alvo a partir de 8 metros&quot;.</p><h3 id="mensuravel" tabindex="-1">Mensurável <a class="header-anchor" href="#mensuravel" aria-label="Permalink to &quot;Mensurável&quot;">​</a></h3><p>Defina como você acompanhará o progresso:</p><ul><li>Percentagens de taxa de sucesso</li><li>Métricas de consistência</li><li>Marcadores de análise de vídeo</li></ul><h3 id="alcancavel-mas-desafiador" tabindex="-1">Alcançável, mas desafiador. <a class="header-anchor" href="#alcancavel-mas-desafiador" aria-label="Permalink to &quot;Alcançável, mas desafiador.&quot;">​</a></h3><p>A meta deve exigir crescimento, mas ser realista. Um jogador com 60% de aproveitamento que almeja 65% é possível; almejar 90% é fantasia.</p><h3 id="relevante" tabindex="-1">Relevante <a class="header-anchor" href="#relevante" aria-label="Permalink to &quot;Relevante&quot;">​</a></h3><p>Os objetivos devem estar conectados às suas aspirações maiores e abordar as fraquezas reais, não apenas aquilo que é fácil de melhorar.</p><h3 id="com-prazo-determinado" tabindex="-1">Com prazo determinado <a class="header-anchor" href="#com-prazo-determinado" aria-label="Permalink to &quot;Com prazo determinado&quot;">​</a></h3><p>Defina prazos claros:</p><ul><li>&quot;Até o final da temporada&quot;</li><li>&quot;Dentro de 3 meses&quot;</li><li>&quot;Pelo campeonato nacional&quot;</li></ul><h3 id="significativo-para-mim" tabindex="-1">+ Significativo para mim <a class="header-anchor" href="#significativo-para-mim" aria-label="Permalink to &quot;+ Significativo para mim&quot;">​</a></h3><p>O objetivo deve ser importante para VOCÊ, não apenas para seu treinador ou colegas de equipe. A motivação interna sustenta o esforço quando o progresso é lento.</p><h2 id="foco-no-processo-versus-foco-no-resultado" tabindex="-1">Foco no processo versus foco no resultado <a class="header-anchor" href="#foco-no-processo-versus-foco-no-resultado" aria-label="Permalink to &quot;Foco no processo versus foco no resultado&quot;">​</a></h2><h3 id="o-problema-com-as-metas-de-resultado" tabindex="-1">O problema com as metas de resultado <a class="header-anchor" href="#o-problema-com-as-metas-de-resultado" aria-label="Permalink to &quot;O problema com as metas de resultado&quot;">​</a></h3><p>&quot;Ganhar a partida&quot; cria problemas:</p><ul><li>Ansiedade em relação a coisas que você não pode controlar.</li><li>Distração da execução</li><li>Pensamento do tipo &quot;tudo ou nada&quot;.</li><li>Pressão sem orientação</li></ul><h3 id="o-poder-das-metas-de-processo" tabindex="-1">O Poder das Metas de Processo <a class="header-anchor" href="#o-poder-das-metas-de-processo" aria-label="Permalink to &quot;O Poder das Metas de Processo&quot;">​</a></h3><p>&quot;Executar minha rotina pré-filme perfeitamente&quot; oferece:</p><ul><li>Controle total</li><li>Foco nítido</li><li>Feedback imediato</li><li>Constrói resultados naturalmente</li></ul><h3 id="o-equilibrio" tabindex="-1">O equilíbrio <a class="header-anchor" href="#o-equilibrio" aria-label="Permalink to &quot;O equilíbrio&quot;">​</a></h3><p>Use metas de resultado para motivação e direção. Use metas de processo para foco e execução diários.</p><h2 id="definicao-de-metas-para-diferentes-fases" tabindex="-1">Definição de metas para diferentes fases <a class="header-anchor" href="#definicao-de-metas-para-diferentes-fases" aria-label="Permalink to &quot;Definição de metas para diferentes fases&quot;">​</a></h2><h3 id="fora-de-temporada" tabindex="-1">Fora de temporada <a class="header-anchor" href="#fora-de-temporada" aria-label="Permalink to &quot;Fora de temporada&quot;">​</a></h3><p>Foco nos objetivos de desenvolvimento:</p><ul><li>Melhorias técnicas</li><li>condicionamento físico</li><li>Desenvolvimento de habilidades mentais</li><li>Ampliando sua paleta de mantas</li></ul><h3 id="pre-temporada" tabindex="-1">Pré-temporada <a class="header-anchor" href="#pre-temporada" aria-label="Permalink to &quot;Pré-temporada&quot;">​</a></h3><p>Transição para a integração:</p><ul><li>Combinar habilidades em condições semelhantes às de uma partida.</li><li>Testando melhorias em competições amistosas</li><li>Aprimorando estratégias</li></ul><h3 id="temporada-de-competicao" tabindex="-1">Temporada de Competição <a class="header-anchor" href="#temporada-de-competicao" aria-label="Permalink to &quot;Temporada de Competição&quot;">​</a></h3><p>Transição para desempenho e processos:</p><ul><li>Executar o que você desenvolveu.</li><li>Objetivos do processo para cada partida</li><li>Alterações técnicas mínimas</li></ul><h3 id="pos-competicao" tabindex="-1">Pós-Competição <a class="header-anchor" href="#pos-competicao" aria-label="Permalink to &quot;Pós-Competição&quot;">​</a></h3><p>Reflexão e planejamento:</p><ul><li>Analise o que funcionou.</li><li>Identificar áreas de crescimento.</li><li>Defina metas para o próximo ciclo.</li></ul><h2 id="erros-comuns-na-definicao-de-metas" tabindex="-1">Erros comuns na definição de metas <a class="header-anchor" href="#erros-comuns-na-definicao-de-metas" aria-label="Permalink to &quot;Erros comuns na definição de metas&quot;">​</a></h2><h3 id="muitos-gols" tabindex="-1">Muitos gols <a class="header-anchor" href="#muitos-gols" aria-label="Permalink to &quot;Muitos gols&quot;">​</a></h3><p>Foco é poder. Dois ou três objetivos principais valem mais do que dez objetivos dispersos.</p><h3 id="apenas-metas-de-resultado" tabindex="-1">Apenas metas de resultado <a class="header-anchor" href="#apenas-metas-de-resultado" aria-label="Permalink to &quot;Apenas metas de resultado&quot;">​</a></h3><p>Sem objetivos de processo, você não tem um roteiro.</p><h3 id="sem-flexibilidade" tabindex="-1">Sem flexibilidade <a class="header-anchor" href="#sem-flexibilidade" aria-label="Permalink to &quot;Sem flexibilidade&quot;">​</a></h3><p>Os objetivos devem se adaptar às novas informações. A adesão rígida a objetivos desatualizados desperdiça esforços.</p><h3 id="metas-baseadas-em-comparacao" tabindex="-1">Metas baseadas em comparação <a class="header-anchor" href="#metas-baseadas-em-comparacao" aria-label="Permalink to &quot;Metas baseadas em comparação&quot;">​</a></h3><p>Dizer &quot;Seja melhor que [jogador]&quot; coloca seu sucesso nas mãos de outra pessoa.</p><h3 id="negligenciar-metas-mentais" tabindex="-1">Negligenciar metas mentais <a class="header-anchor" href="#negligenciar-metas-mentais" aria-label="Permalink to &quot;Negligenciar metas mentais&quot;">​</a></h3><p>Os objetivos técnicos e físicos predominam, mas as habilidades mentais muitas vezes determinam o vencedor.</p><h2 id="estrategias-de-implementacao" tabindex="-1">Estratégias de Implementação <a class="header-anchor" href="#estrategias-de-implementacao" aria-label="Permalink to &quot;Estratégias de Implementação&quot;">​</a></h2><h3 id="anote-os" tabindex="-1">Anote-os <a class="header-anchor" href="#anote-os" aria-label="Permalink to &quot;Anote-os&quot;">​</a></h3><p>Metas escritas têm uma probabilidade significativamente maior de serem alcançadas.</p><h3 id="revise-regularmente" tabindex="-1">Revise regularmente <a class="header-anchor" href="#revise-regularmente" aria-label="Permalink to &quot;Revise regularmente&quot;">​</a></h3><p>A revisão semanal mantém os objetivos presentes e permite ajustes.</p><h3 id="compartilhar-seletivamente" tabindex="-1">Compartilhar Seletivamente <a class="header-anchor" href="#compartilhar-seletivamente" aria-label="Permalink to &quot;Compartilhar Seletivamente&quot;">​</a></h3><p>Compartilhe com aqueles que irão apoiar, e não sabotar.</p><h3 id="visualize-a-conquista" tabindex="-1">Visualize a Conquista <a class="header-anchor" href="#visualize-a-conquista" aria-label="Permalink to &quot;Visualize a Conquista&quot;">​</a></h3><p>Imagine regularmente a conquista dos seus objetivos — a sensação, o momento.</p><h3 id="acompanhe-o-progresso" tabindex="-1">Acompanhe o progresso <a class="header-anchor" href="#acompanhe-o-progresso" aria-label="Permalink to &quot;Acompanhe o progresso&quot;">​</a></h3><p>O que é medido é gerenciado. Mantenha registros.</p><h2 id="quando-as-metas-nao-sao-atingidas" tabindex="-1">Quando as metas não são atingidas <a class="header-anchor" href="#quando-as-metas-nao-sao-atingidas" aria-label="Permalink to &quot;Quando as metas não são atingidas&quot;">​</a></h2><p>Metas não atingidas não são fracassos — são dados:</p><ol><li><strong>Analise</strong>: Por que isso não foi alcançado?</li><li><strong>Aprenda</strong>: O que isso te ensina?</li><li><strong>Ajustar</strong>: Modificar a meta ou a abordagem.</li><li><strong>Continuação:</strong> A persistência vence a perfeição.</li></ol><h2 id="o-jogo-mental-dos-objetivos" tabindex="-1">O Jogo Mental dos Objetivos <a class="header-anchor" href="#o-jogo-mental-dos-objetivos" aria-label="Permalink to &quot;O Jogo Mental dos Objetivos&quot;">​</a></h2><p>Os objetivos afetam a psicologia:</p><ul><li><strong>Muito fácil</strong>: Tédio, complacência</li><li><strong>Muito difícil</strong>: Ansiedade, desânimo</li><li><strong>Na medida certa</strong>: Engajamento, fluidez, crescimento</li></ul><p>Encontre o ponto ideal em que as metas sejam desafiadoras sem serem avassaladoras.</p><hr><p>| <em>Relacionado: <a href="/en/education/goals/">Introdução à definição de metas</a> | <a href="/en/education/goals/smart-goals">Metas SMART</a> | <a href="/en/education/goals/planning">Planejando seu desenvolvimento</a></em> |</p>',88)])])}]]);export{i as __pageData,t as default};
